class Solution {
public:
    int minOperations(std::vector<int>& nums) {
        int n = nums.size();
        int c1 = 0;
        for (int x : nums) if (x == 1) c1++;
        if (c1 > 0) return n - c1;
        int min_len = 1e9;
        for (int i = 0; i < n; i++) {
            int g = nums[i];
            for (int j = i + 1; j < n; j++) {
                g = std::gcd(g, nums[j]);
                if (g == 1) {
                    min_len = std::min(min_len, j - i + 1);
                    break;
                }
            }
        }
        if (min_len == 1e9) return -1;
        return min_len - 1 + n - 1;
    }
};

class Solution {
    public int minOperations(int[] nums) {
        int n = nums.length;
        int c1 = 0;
        for (int x : nums) if (x == 1) c1++;
        if (c1 > 0) return n - c1;
        int minLen = Integer.MAX_VALUE;
        for (int i = 0; i < n; i++) {
            int g = nums[i];
            for (int j = i + 1; j < n; j++) {
                g = gcd(g, nums[j]);
                if (g == 1) {
                    minLen = Math.min(minLen, j - i + 1);
                    break;
                }
            }
        }
        if (minLen == Integer.MAX_VALUE) return -1;
        return minLen - 1 + n - 1;
    }

    private int gcd(int a, int b) {
        return b == 0 ? a : gcd(b, a % b);
    }
}

var minOperations = function(nums) {
    const n = nums.length;
    let c1 = 0;
    for (const x of nums) if (x === 1) c1++;
    if (c1 > 0) return n - c1;
    function gcd(a, b) {
        return b === 0 ? a : gcd(b, a % b);
    }
    let minLen = Infinity;
    for (let i = 0; i < n; i++) {
        let g = nums[i];
        for (let j = i + 1; j < n; j++) {
            g = gcd(g, nums[j]);
            if (g === 1) {
                minLen = Math.min(minLen, j - i + 1);
                break;
            }
        }
    }
    if (minLen === Infinity) return -1;
    return minLen - 1 + n - 1;
};
